package io.metersphere.agent.service;

import org.junit.jupiter.api.*;
import io.metersphere.sdk.exception.MSException;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class AgentStructuredProtocolTests extends AgentProtocolTransactionTests {
    AgentStructuredContractService contracts;
    @BeforeEach void contracts(){jdbc.execute("CREATE TABLE functional_case(id VARCHAR(64) PRIMARY KEY,project_id VARCHAR(64),deleted BOOLEAN,version_id VARCHAR(64))");jdbc.update("INSERT INTO functional_case VALUES ('case','project',false,'definition-1')");var access=mock(AgentProtocolAccess.class);when(access.organizationForProject("project")).thenReturn("org");when(access.actor(eq("org"),anyBoolean())).thenReturn(new AgentProtocolAccess.Actor("org","author","HUMAN","author-person",true));when(access.sessionActor(eq("org"),anyBoolean())).thenReturn(new AgentProtocolAccess.Actor("org","author","HUMAN","author-person",true));var config=mock(AgentSessionProtocolConfiguration.class);when(config.number("limits.content-utf8-bytes")).thenReturn(100000L);when(config.number("limits.reference-scalars")).thenReturn(100000L);contracts=new AgentStructuredContractService(jdbc,store,access,config);}
    Map<String,Object> content(){var value=new LinkedHashMap<String,Object>();value.put("schemaVersion","1.0");value.put("goal","verify authorized order");value.put("preconditions","no prerequisites");value.put("environmentId","test");value.put("riskBoundary","owned data only");value.put("allowedActions",List.of());value.put("steps",List.of(Map.of("id","S1","sourcePosition",1,"action","inspect original order","expectedObservation","visible","inputBindings",Map.of())));value.put("assertions",List.of(Map.of("id","A1","required",true,"stepId","S1","entryPoint","order detail","expected","visible","evidenceTypes",List.of("IMAGE"),"objectFields",List.of("id"),"verificationMethod","INDEPENDENT_HUMAN","failureRule","not visible")));value.put("dataRequirements",List.of());value.put("dependencies",List.of());value.put("knowledgeRefs",List.of());value.put("outputs",Map.of());value.put("variables",Map.of());return value;}
    @Test void publishedVersionIsImmutableAndFreezesActualCaseDefinition(){var first=contracts.save("project","case",Map.of("idempotencyKey","first","expectedVersion",0,"content",content(),"publish",true));assertEquals(1L,first.get("version"));var revised=content();revised.put("goal","new draft goal");contracts.save("project","case",Map.of("idempotencyKey","second","expectedVersion",1,"content",revised,"publish",false));var original=contracts.published("project","case",1);assertEquals("verify authorized order",original.get("goal"));assertEquals("definition-1",original.get("sourceVersion"));assertEquals("author-person",original.get("authorPerson"));}
    @Test void duplicateSourcePositionsAndNoRequiredAssertionsCannotBePublished(){var duplicate=content();duplicate.put("steps",List.of(Map.of("id","S1","sourcePosition",1,"action","a","expectedObservation","a"),Map.of("id","S2","sourcePosition",1,"action","b","expectedObservation","b")));assertThrows(MSException.class,()->contracts.validate("project","case",duplicate,true));var empty=content();empty.put("assertions",List.of());assertTrue(contracts.validate("project","case",empty,false).contains("NO_REQUIRED_ASSERTION"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM msp_case_contract",Integer.class));}
    @Test void arbitraryExpressionsAndMissingDataReferencesRemainDraftIssues(){var value=content();value.put("steps",List.of(Map.of("id","S1","sourcePosition",1,"action","a","expectedObservation","a","inputBindings",Map.of("id","data.missing.id","unsafe","${execute()}"))));var issues=contracts.validate("project","case",value,false);assertTrue(issues.contains("VARIABLE_SYNTAX_INVALID"));assertTrue(issues.contains("VARIABLE_UNDECLARED"));assertThrows(MSException.class,()->contracts.save("project","case",Map.of("idempotencyKey","unsafe","expectedVersion",0,"content",value,"publish",true)));}
    @Test void typedValuesRejectImplicitConversionNullabilityAndLossyPackaging(){var spec=Map.<String,Object>of("amount",Map.of("type","number","minimum",0,"maximum",10,"unit","CNY"));assertThrows(MSException.class,()->AgentProtocolTypes.values(spec,Map.of("amount","2"),true));assertThrows(MSException.class,()->AgentProtocolTypes.values(spec,Map.of("amount",11),true));var nested=Map.<String,Object>of("payload",Map.of("type","object","properties",spec));assertEquals(Set.of("payload.amount"),AgentProtocolTypes.leafFields(nested).keySet());assertThrows(MSException.class,()->AgentProtocolTypes.values(nested,Map.of("payload",Map.of("amount","2")),true));assertFalse(AgentProtocolTypes.compatible(Map.of("type","number","unit","CNY"),Map.of("type","number","unit","USD")));var nullable=new LinkedHashMap<String,Object>();nullable.put("amount",null);assertThrows(MSException.class,()->AgentProtocolTypes.values(spec,nullable,true));}
}
